// Builds the static site into dist/: fills the sketch slots in src/index.html with
// hand-drawn SVG generated by rough.js, so the published page needs no JavaScript library.
const fs = require("fs");
const path = require("path");
const rough = require("roughjs/bundled/rough.cjs.js");

const gen = rough.generator();
const PEN = "var(--pen)", INK = "var(--ink)", MARK = "var(--marker)", MUTE = "var(--graphite)";
let seed = 7;

// one rough drawable -> <path> elements; pathLength=1 lets CSS draw any stroke in
function paths(drawable, cls = "") {
  return gen.toPaths(drawable).map((p) => {
    const fill = p.fill && p.fill !== "none" ? p.fill : "none";
    return `<path d="${p.d.replace(/-?\d+\.\d+/g, (n) => (+n).toFixed(1))}" stroke="${p.stroke}" stroke-width="${p.strokeWidth}" fill="${fill}" pathLength="1" class="${cls}"/>`;
  }).join("");
}
const o = (x = {}) => Object.assign({ seed: seed++, roughness: 1.1, bowing: 1.2, stroke: PEN, strokeWidth: 2 }, x);
const box = (x, y, w, h, opt, cls) => paths(gen.rectangle(x, y, w, h, o(opt)), cls);
const line = (x1, y1, x2, y2, opt, cls) => paths(gen.line(x1, y1, x2, y2, o(opt)), cls);
const ell = (cx, cy, w, h, opt, cls) => paths(gen.ellipse(cx, cy, w, h, o(opt)), cls);
const curve = (pts, opt, cls) => paths(gen.curve(pts, o(opt)), cls);
function arrow(x1, y1, x2, y2, opt = {}, cls = "") {
  const a = Math.atan2(y2 - y1, x2 - x1), L = 13;
  const h1 = [x2 - L * Math.cos(a - 0.45), y2 - L * Math.sin(a - 0.45)];
  const h2 = [x2 - L * Math.cos(a + 0.45), y2 - L * Math.sin(a + 0.45)];
  return line(x1, y1, x2, y2, opt, cls) + line(x2, y2, ...h1, opt, cls) + line(x2, y2, ...h2, opt, cls);
}
const hand = (x, y, t, size = 20, fill = PEN, extra = "") =>
  `<text x="${x}" y="${y}" font-family="Kalam, cursive" font-size="${size}" fill="${fill}" ${extra}>${t}</text>`;
const label = (x, y, t, size = 17, weight = 700, fill = INK, anchor = "middle") =>
  `<text x="${x}" y="${y}" font-family="'Lumenar Sans', system-ui, sans-serif" font-size="${size}" font-weight="${weight}" fill="${fill}" text-anchor="${anchor}">${t}</text>`;
const svg = (w, h, body, title, cls = "") =>
  `<svg class="sketch ${cls}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${title}" fill="none" stroke-linecap="round" stroke-linejoin="round"><title>${title}</title>${body}</svg>`;

// ---------- hero: one session moves from model A to model B, memory kept ----------
function hero() {
  let b = "";
  b += box(30, 30, 170, 64, {}, "d1") + label(115, 69, "your agent");
  b += arrow(115, 100, 245, 172, {}, "d2");
  b += hand(186, 128, "every turn", 18, MUTE);
  b += box(220, 180, 220, 92, { strokeWidth: 2.6, stroke: INK }, "d3") + box(226, 186, 208, 80, { stroke: INK, strokeWidth: 1, roughness: 1.6 }, "d3");
  b += label(330, 224, "Lumenar", 24, 800) + label(330, 251, "session layer", 15, 400, MUTE);
  // session log: a little stack of pages
  b += box(476, 166, 82, 100, { stroke: INK, fill: "#FFFFFF", fillStyle: "solid" }, "d4") + box(470, 172, 82, 100, { stroke: INK, fill: "#FFFFFF", fillStyle: "solid" }, "d4");
  for (let i = 0; i < 4; i++) b += line(482, 194 + i * 17, 540 - (i % 2) * 16, 194 + i * 17, { stroke: MUTE, strokeWidth: 1.4 }, "d4");
  b += line(440, 226, 468, 222, { stroke: INK }, "d4");
  b += hand(514, 154, "session log", 19, PEN, 'text-anchor="middle"') + hand(514, 298, "not tied to any model", 16, MUTE, 'text-anchor="middle"');
  // model A and B
  b += box(20, 380, 180, 70, {}, "d5") + label(110, 412, "Model A") + label(110, 434, "turns 1 - 29", 14, 400, MUTE);
  b += arrow(268, 278, 150, 372, {}, "d5");
  b += box(400, 380, 180, 70, {}, "d6") + label(490, 412, "Model B") + label(490, 434, "turn 30 onward", 14, 400, MUTE);
  b += arrow(392, 278, 470, 372, { strokeWidth: 2.4 }, "d6");
  b += hand(454, 346, "switch at turn 30", 19, PEN, 'text-anchor="start"');
  // the payoff, circled
  b += hand(330, 504, "same plan, same files, cache warmed once", 21, INK, 'text-anchor="middle"');
  b += ell(330, 497, 440, 58, { stroke: PEN, roughness: 1.6, strokeWidth: 1.8 }, "d7");
  b += curve([[488, 455], [474, 466], [462, 470]], { strokeWidth: 1.6 }, "d7");
  return svg(640, 540, b, "Diagram: your agent talks to the Lumenar session layer, which keeps a session log. Turns 1 to 29 run on model A; at turn 30 the session moves to model B with the same plan and files and a cache warmed once.", "hero-sketch");
}

// ---------- re-send tax: tokens sent each turn ----------
function resend() {
  let b = "";
  const vals = [12, 24, 36, 48, 60, 72, 84];
  vals.forEach((v, i) => {
    const x = 40 + i * 62, h = v * 2.6;
    b += box(x, 250 - h, 40, h, { stroke: INK, fill: i === 6 ? MARK : MUTE, fillStyle: i === 6 ? "solid" : "hachure", hachureGap: 6, fillWeight: 1.2, strokeWidth: 1.6 });
    b += label(x + 20, 244 - h, String(v) + "K", 13, 600, INK);
    b += label(x + 20, 274, ["1", "10", "20", "30", "40", "50", "60"][i], 13, 400, MUTE);
  });
  b += line(26, 252, 480, 252, { stroke: INK, strokeWidth: 1.6 });
  b += label(250, 300, "turn", 13, 400, MUTE);
  b += hand(40, 30, "the whole history is sent again, every turn", 19, PEN, 'text-anchor="start"');
  return svg(500, 310, b, "Bar chart of an illustrative 60-turn task: tokens sent per turn grow from 12 thousand at turn 1 to 84 thousand at turn 60.");
}

// ---------- four mechanisms: small sketches ----------
function mini(kind) {
  let b = "";
  if (kind === "sticky") {
    b += box(10, 20, 60, 34, { stroke: INK }) + label(40, 42, "session", 12, 600);
    b += box(130, 6, 70, 30, { stroke: MUTE, strokeWidth: 1.4 }) + label(165, 26, "GPU 1", 12, 400, MUTE);
    b += box(130, 48, 70, 30, { stroke: INK, fill: MARK, fillStyle: "solid" }) + label(165, 68, "GPU 2", 12, 700);
    b += arrow(74, 40, 124, 60);
    b += hand(206, 70, "has its cache", 15, PEN, 'text-anchor="start"');
  } else if (kind === "append") {
    [["system", 70], ["tools", 60], ["repo map", 80], ["turns", 46]].forEach(([t, w], i) => {
      const x = 8 + [0, 74, 138, 222][i];
      b += box(x, 26, w, 34, { stroke: INK, fill: i < 3 ? "#E9EDF7" : MARK, fillStyle: "solid", strokeWidth: 1.5 }) + label(x + w / 2, 48, t, 12, 600);
    });
    b += arrow(270, 76, 300, 76, { strokeWidth: 1.6 });
    b += hand(140, 90, "stable first, new last", 15, PEN);
  } else if (kind === "route") {
    b += box(8, 30, 66, 32, { stroke: INK }) + label(41, 51, "step", 12, 600);
    b += arrow(78, 40, 140, 16) + arrow(78, 54, 140, 76);
    b += box(146, 2, 108, 28, { stroke: INK, strokeWidth: 1.5 }) + label(200, 21, "small model", 12, 600);
    b += box(146, 62, 108, 28, { stroke: INK, strokeWidth: 1.5 }) + label(200, 81, "large model", 12, 600);
    b += hand(262, 22, "read, search", 14, MUTE, 'text-anchor="start"') + hand(262, 82, "plan, debug", 14, MUTE, 'text-anchor="start"');
  } else {
    b += box(8, 26, 70, 40, { stroke: INK }) + label(43, 51, "A", 14, 700);
    b += box(226, 26, 70, 40, { stroke: INK }) + label(261, 51, "B", 14, 700);
    b += box(128, 30, 50, 34, { stroke: PEN, fill: "#FFFFFF", fillStyle: "solid" });
    b += line(136, 42, 170, 42, { stroke: MUTE, strokeWidth: 1.2 }) + line(136, 52, 162, 52, { stroke: MUTE, strokeWidth: 1.2 });
    b += arrow(82, 46, 122, 46, { strokeWidth: 1.6 }) + arrow(182, 46, 220, 46, { strokeWidth: 1.6 });
    b += hand(153, 90, "log goes along", 15, PEN, 'text-anchor="middle"');
  }
  return svg(380, 100, b, "", "mini");
}

// ---------- six-step handoff (a real sequence) ----------
function handoff() {
  const steps = ["freeze", "compact", "render", "warm up", "check", "go on"];
  let b = curve([[40, 70], [200, 52], [380, 86], [560, 56], [740, 82], [900, 64]], { strokeWidth: 1.6, stroke: MUTE, roughness: 1.4 });
  steps.forEach((t, i) => {
    const x = 60 + i * 168, y = [66, 58, 76, 70, 62, 72][i];
    b += ell(x, y, 46, 46, { stroke: INK, fill: i === 5 ? MARK : "#FFFFFF", fillStyle: "solid", strokeWidth: 1.8 });
    b += label(x, y + 6, String(i + 1), 17, 800);
    b += hand(x, y + 58, t, 21, INK, 'text-anchor="middle"');
  });
  return svg(960, 150, b, "Six steps in a model switch: freeze, compact, render, warm up, check, go on.", "handoff-sketch");
}

// ---------- cost model chart ----------
function impact() {
  const rows = [["No reuse", 2.95, MUTE, "hachure"], ["+ prefix cache", 0.47, INK, "hachure"], ["+ cache + step routing", 0.30, MARK, "solid"]];
  let b = "";
  rows.forEach(([t, v, c, fs], i) => {
    const y = 30 + i * 74, w = Math.max(18, v * 150);
    b += label(190, y + 31, t, 17, 600, INK, "end");
    b += box(206, y + 6, w, 40, { stroke: INK, fill: c, fillStyle: fs, hachureGap: 6, strokeWidth: 1.6 });
    b += hand(214 + w, y + 35, "$" + v.toFixed(2), 25, INK, 'text-anchor="start"');
  });
  b += hand(206, 258, "cost model with stated assumptions, not a measurement", 18, PEN, 'text-anchor="start"');
  return svg(720, 272, b, "Cost model for one 60-turn example task: 2.95 dollars with no reuse, 0.47 with a prefix cache, 0.30 with cache plus step routing. Not measured.");
}

const marks = {
  check: () => svg(28, 28, curve([[4, 15], [11, 23], [25, 5]], { strokeWidth: 2.4, stroke: INK }), "done", "mark"),
  open: () => svg(28, 28, ell(14, 14, 20, 20, { strokeWidth: 1.8, stroke: MUTE }), "not yet", "mark"),
  underline: () => svg(300, 16, curve([[4, 10], [100, 5], [200, 11], [296, 6]], { strokeWidth: 3, stroke: MARK, roughness: 0.8 }), "", "uline"),
};

let html = fs.readFileSync(path.join(__dirname, "src/index.html"), "utf8");
const slots = {
  hero: hero(), resend: resend(), handoff: handoff(), impact: impact(),
  "mini-sticky": mini("sticky"), "mini-append": mini("append"), "mini-route": mini("route"), "mini-handoff": mini("handoff"),
};
html = html.replace(/<!--sketch:([a-z-]+)-->/g, (m, k) => {
  if (slots[k]) return slots[k];
  if (marks[k]) return marks[k]();
  throw new Error("unknown sketch slot " + k);
});

const out = path.join(__dirname, "dist");
fs.rmSync(out, { recursive: true, force: true });
fs.cpSync(path.join(__dirname, "public"), out, { recursive: true });
fs.copyFileSync(path.join(__dirname, "src/style.css"), path.join(out, "style.css"));
fs.writeFileSync(path.join(out, "index.html"), html);
console.log("built dist/ (" + Math.round(html.length / 1024) + " KB html)");
